export default{inject:{pageBridge:{from:'page'}},data(){return{rows:[],page:{page:1,pageSize:10,totalRows:0,totalPages:1},summary:{},keyword:'',reasonCode:'',loading:false,error:'',selected:null,relistNote:'',saving:false,dialogError:'',history:[],historyLoading:false,reasons:[{value:'OWNER_REQUEST',label:'业主要求下架'},{value:'TEMPORARY_HOLD',label:'暂缓出租'},{value:'RENOVATION',label:'装修或维修'},{value:'SOLD_OR_TRANSFERRED',label:'出售或转让'},{value:'DATA_CLEANUP',label:'资料整理'},{value:'OTHER',label:'其他原因'}]};},mounted(){this.load();},methods:{async load(){this.loading=true;this.error='';try{const d=await fetchAdminOffMarketProperties({page:this.page.page,pageSize:this.page.pageSize,keyword:this.keyword,reasonCode:this.reasonCode});this.rows=d.rows||[];this.page=d.page||this.page;this.summary=d.summary||{};}catch(e){this.error=e.message||'下架房源载入失败';}finally{this.loading=false;}},reloadFirst(){this.page.page=1;this.load();},reset(){this.keyword='';this.reasonCode='';this.reloadFirst();},go(v){this.page.page=v;this.load();},reasonLabel(v){return this.reasons.find(x=>x.value===v)?.label||v||'未说明';},listingLabel(v){return({available:'可出租',reserved:'已预留',rented:'出租中',occupied:'已入住',inactive:'停用',sold:'已出售'})[v]||v||'未设置';},dateTime(v){return v?String(v).replace('T',' ').slice(0,16):'—';},view(i){navigate(`/admin/off-market-rentals/${i.unitId}`);},openRelist(i){this.selected=i;this.relistNote='';this.dialogError='';this.$refs.relistDialog.showModal();},closeRelist(){this.$refs.relistDialog?.close();},async confirmRelist(){if(!this.selected)return;this.saving=true;this.dialogError='';try{await relistAdminProperty(this.selected.unitId,{note:this.relistNote});this.closeRelist();this.pageBridge.showToast('出租房源已重新上架，原有资料完整保留');await this.load();}catch(e){this.dialogError=e.message||'重新上架失败';}finally{this.saving=false;}},async showHistory(i){this.selected=i;this.history=[];this.historyLoading=true;this.$refs.historyDialog.showModal();try{this.history=await fetchAdminPropertyManagementHistory